svg.script:
(() => {
  const tintFills = Array.from(document.querySelectorAll(".renmi-tint-fill"));
  const tintColorPattern = /^#[0-9a-f]{6}$/i;
  window.__clawdSetPetTint = (color) => {
    const next = typeof color === "string" && tintColorPattern.test(color)
      ? color
      : "transparent";
    for (const fill of tintFills) fill.setAttribute("fill", next);
  };

  const tail = document.getElementById("tail-swing-js");
  if (!tail) return;

  const PIVOT_X = 1045;
  const PIVOT_Y = 1015;
  const ACTION_MS = 1900;
  const MIN_REST_MS = 10000;
  const MAX_REST_MS = 60000;
  const WAG_KEYS = [
    { at: 0.00, angle: 0 },
    { at: 0.16, angle: 16 },
    { at: 0.34, angle: -16 },
    { at: 0.52, angle: 13 },
    { at: 0.68, angle: -11 },
    { at: 0.82, angle: 7 },
    { at: 1.00, angle: 0 },
  ];

  let phase = "rest";
  let lowPowerPaused = false;
  let restTimer = 0;
  let restDeadline = 0;
  let restRemaining = 0;
  let rafId = 0;
  let actionStart = 0;
  let actionElapsed = 0;

  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const isDocumentVisible = () => document.visibilityState !== "hidden";

  function setTailAngle(angle) {
    tail.setAttribute("transform", `rotate(${angle} ${PIVOT_X} ${PIVOT_Y})`);
  }

  function clearRestTimer() {
    if (restTimer) clearTimeout(restTimer);
    restTimer = 0;
    restDeadline = 0;
  }

  function randomRestMs() {
    return MIN_REST_MS + Math.floor(Math.random() * (MAX_REST_MS - MIN_REST_MS + 1));
  }

  function easeInOut(value) {
    return value * value * (3 - 2 * value);
  }

  function angleAt(progress) {
    const t = clamp(progress, 0, 1);
    for (let index = 1; index < WAG_KEYS.length; index += 1) {
      const next = WAG_KEYS[index];
      if (t > next.at) continue;
      const previous = WAG_KEYS[index - 1];
      const segment = (t - previous.at) / (next.at - previous.at);
      const eased = easeInOut(clamp(segment, 0, 1));
      return previous.angle + (next.angle - previous.angle) * eased;
    }
    return WAG_KEYS[WAG_KEYS.length - 1].angle;
  }

  function requestActionFrame() {
    if (!lowPowerPaused && phase === "wag" && !rafId) {
      rafId = requestAnimationFrame(step);
    }
  }

  function scheduleRest(delayMs = randomRestMs()) {
    clearRestTimer();
    phase = "rest";
    actionElapsed = 0;
    const requested = Number(delayMs);
    restRemaining = Number.isFinite(requested) ? Math.max(0, requested) : MIN_REST_MS;
    if (lowPowerPaused) return;

    restDeadline = performance.now() + restRemaining;
    restTimer = setTimeout(() => {
      restTimer = 0;
      restDeadline = 0;
      restRemaining = 0;
      if (!lowPowerPaused && isDocumentVisible()) startWag();
    }, restRemaining);
  }

  function startWag() {
    if (lowPowerPaused || !isDocumentVisible()) return;
    phase = "wag";
    actionStart = performance.now() - actionElapsed;
    requestActionFrame();
  }

  function recoverFromAnimationError() {
    if (rafId) cancelAnimationFrame(rafId);
    rafId = 0;
    setTailAngle(0);
    scheduleRest();
  }

  function step(now) {
    rafId = 0;
    if (lowPowerPaused || phase !== "wag") return;
    try {
      actionElapsed = clamp(now - actionStart, 0, ACTION_MS);
      setTailAngle(angleAt(actionElapsed / ACTION_MS));
      if (actionElapsed < ACTION_MS) {
        requestActionFrame();
        return;
      }
      setTailAngle(0);
      scheduleRest();
    } catch {
      recoverFromAnimationError();
    }
  }

  function pauseForHiddenDocument() {
    if (phase === "rest") {
      if (restTimer) restRemaining = Math.max(0, restDeadline - performance.now());
      clearRestTimer();
    } else if (phase === "wag") {
      actionElapsed = clamp(performance.now() - actionStart, 0, ACTION_MS);
      if (rafId) cancelAnimationFrame(rafId);
      rafId = 0;
    }
  }

  window.__clawdSetLowPowerPaused = (paused) => {
    const next = !!paused;
    if (next === lowPowerPaused) return;
    lowPowerPaused = next;
    if (next) {
      if (phase === "rest" && restTimer) restRemaining = Math.max(0, restDeadline - performance.now());
      clearRestTimer();
      if (rafId) cancelAnimationFrame(rafId);
      rafId = 0;
      return;
    }
    if (!isDocumentVisible()) return;
    if (phase === "rest") {
      if (restRemaining <= 0) startWag();
      else scheduleRest(restRemaining);
    } else {
      actionStart = performance.now() - actionElapsed;
      requestActionFrame();
    }
  };

  document.addEventListener("visibilitychange", () => {
    if (!isDocumentVisible()) {
      pauseForHiddenDocument();
      return;
    }
    if (lowPowerPaused) return;
    if (phase === "rest") {
      if (restRemaining <= 0) startWag();
      else scheduleRest(restRemaining);
    } else {
      actionStart = performance.now() - actionElapsed;
      requestActionFrame();
    }
  });

  setTailAngle(0);
  scheduleRest();
})();
